public boolean tryAccess(String key, int seconds, int limitCount) {
		LimitRule limitRule = new LimitRule();
		limitRule.setLimitCount(limitCount);
		limitRule.setSeconds(seconds);
		return tryAccess(key, limitRule);
	}
